(function(){
 'use strict';
 const D=window.researchVisualData;
 const modes={rates:'Group rates',difference:'The extra effect',uncertainty:'How certain?',checks:'Robustness',quality:'Data limits'};
 const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const f=v=>Math.abs(v).toFixed(1),signed=v=>(v<0?'−':'+')+f(v),pct=v=>f(v)+'%',pval=v=>v<.001?v.toFixed(5):v.toFixed(3),count=v=>v.toLocaleString('en-US');
 function state(){const p=new URLSearchParams(location.search);return {mode:Object.hasOwn(modes,p.get('visual'))?p.get('visual'):'rates',chart:p.get('chart')==='pies'?'pies':'bars'};}
 function donut(value,total,label){const ratio=value/total,angle=ratio*360;return `<div class="pie-wrap"><svg class="pie-chart" viewBox="0 0 160 160" role="img" aria-label="${safe(label)}: ${pct(ratio*100)} recorded departed, ${count(value)} of ${count(total)}"><title>${safe(label)}: ${pct(ratio*100)} recorded departed</title><circle cx="80" cy="80" r="59" fill="none" stroke="#e0e7f0" stroke-width="22"/><circle cx="80" cy="80" r="59" fill="none" stroke="#285fd6" stroke-width="22" pathLength="100" stroke-dasharray="${ratio*100} ${100-ratio*100}" transform="rotate(-90 80 80)"/><text x="80" y="78" text-anchor="middle" class="pie-value">${pct(ratio*100)}</text><text x="80" y="98" text-anchor="middle" class="pie-caption">departed</text></svg></div>`;}
 function rateBars(g){return `<div class="rate-bars">${g.arms.map((a,i)=>`<div class="rate-row"><div class="rate-line"><span>${a.label}</span><strong>${pct(a.rate)}</strong></div><div class="rate-track" role="img" aria-label="${g.label}, ${a.label}: ${pct(a.rate)} recorded departed; ${count(a.departed)} of ${count(a.n)} children"><div class="rate-fill ${i?'program':'control'}" style="width:${a.rate}%"></div></div><p class="mark-note">${count(a.departed)} of ${count(a.n)} children classified as departed</p></div>`).join('')}<div class="rate-axis"><span>0%</span><span>50%</span><span>100%</span></div></div>`;}
 function rates(s){return `<div class="viz-heading"><div><span class="viz-kicker">01 · Start with the observed proportions</span><h2 id="visual-title">The departure gap is larger among baseline writers.</h2></div><div class="chart-switch" role="group" aria-label="Chart type"><button data-chart="bars" aria-pressed="${s.chart==='bars'}">Bars</button><button data-chart="pies" aria-pressed="${s.chart==='pies'}">Pies</button></div></div><p class="viz-intro">Compare <strong>control versus program within each group</strong>. These are different children in randomized schools, not the same children before and after treatment.</p>${s.chart==='pies'?'<div class="viz-key"><span><i class="key-dot"></i>Classified as departed</span><span><i class="key-dot gray"></i>Not classified as departed</span></div>':''}<div class="rate-groups">${D.groups.map(g=>`<figure class="rate-group"><figcaption><h3>${g.label}</h3><p>${g.description}</p></figcaption>${s.chart==='bars'?rateBars(g):`<div class="pie-pair">${g.arms.map(a=>`<div class="pie-cell"><strong>${a.label}</strong>${donut(a.departed,a.n,g.label+', '+a.label)}<p><strong>${count(a.departed)} / ${count(a.n)}</strong> departed</p><p class="mark-note">${count(a.notDeparted)} not classified as departed</p></div>`).join('')}</div>`}<div class="group-gap"><span>Program − control</span><strong>${signed(g.effect)} <small>percentage points</small></strong></div></figure>`).join('')}</div><div class="viz-takeaway"><strong>Compare the increases, not just the group totals.</strong><span>+26.1 − +5.0 = <b>+21.1 percentage points</b>. That difference is the new research finding.</span><button class="viz-next" data-visual="difference">See the calculation →</button></div><p class="viz-source">${s.chart==='pies'?'Each pie represents its own group; equal-sized pies do not mean equal sample sizes. ':''}“Not classified as departed” does not prove continued enrollment. Departure follows the original attendance-based rule; later educational destinations are uncertain.</p>`;}
 function difference(){return `<div class="viz-heading"><div><span class="viz-kicker">02 · From rates to the research comparison</span><h2 id="visual-title">A +21.1-point difference between program effects.</h2></div></div><div class="calc-equation"><div><span>Writers: program − control</span><strong>70.4% − 44.3%</strong><b>+26.1 points</b></div><span class="calc-symbol" aria-hidden="true">−</span><div><span>Nonwriters: program − control</span><strong>38.8% − 33.8%</strong><b>+5.0 points</b></div><span class="calc-symbol" aria-hidden="true">=</span><div class="calc-answer"><span>Difference between effects</span><strong>+21.1</strong><b>percentage points</b></div></div><figure class="effect-bars"><figcaption>Increase in recorded departure, program versus control</figcaption>${D.groups.map(g=>`<div class="effect-bar-row"><div><span>${g.label}</span><strong>${signed(g.effect)} points</strong></div><div class="effect-track"><i style="width:${g.effect/30*100}%"></i></div></div>`).join('')}<div class="rate-axis"><span>0</span><span>15</span><span>30 points</span></div></figure><div class="original-anchor"><span class="viz-kicker">Original paper → new extension</span><p>The replicated original result is an average <strong>+${f(D.originalMeanEffect)}-point</strong> increase in departure. Our extension asks whether this response differs by initial preparation.</p><p class="mark-note">Original replication: ${count(D.originalN)} children. Linked writing-status analysis: ${count(D.n)}, after excluding two conflicting IDs. The +21.1 points is a difference between effects, not the overall departure rate or an average effect.</p></div><div class="viz-takeaway"><strong>Is the difference statistically distinguishable from zero?</strong><button class="viz-next" data-visual="uncertainty">Look at the confidence intervals →</button></div>`;}
 const pos=v=>(v+10)/60*100;
 function forest(rows){return `<div class="forest" role="group" aria-label="Estimates and 95 percent confidence intervals, in percentage points"><div class="forest-zero-note">Dashed line = no difference (0)</div>${rows.map((r,i)=>`<figure class="forest-row ${r.focus?'focus':''}"><figcaption><span>${r.label}</span><strong>${signed(r.effect)} <small>[${signed(r.low)}, ${signed(r.high)}]</small></strong></figcaption><div class="interval-plot" role="img" aria-label="${safe(r.label)}: ${signed(r.effect)} percentage points, 95 percent confidence interval ${signed(r.low)} to ${signed(r.high)}"><i class="zero-line" style="left:${pos(0)}%"></i><span class="ci-range" style="left:${pos(r.low)}%;width:${pos(r.high)-pos(r.low)}%"></span><span class="ci-cap" style="left:${pos(r.low)}%"></span><span class="ci-cap" style="left:${pos(r.high)}%"></span><span class="estimate-dot" style="left:${pos(r.effect)}%"></span></div><p class="interval-note">${r.note||('Two-sided p = '+pval(r.p))}</p></figure>`).join('')}<div class="forest-axis">${[-10,0,10,20,30,40,50].map(n=>`<span style="left:${pos(n)}%">${n<0?'−'+Math.abs(n):n}</span>`).join('')}</div><p class="axis-title">Difference in percentage points</p></div>`;}
 function uncertainty(){const main=D.checks[0];return `<div class="viz-heading"><div><span class="viz-kicker">03 · Read the uncertainty, not just the dot</span><h2 id="visual-title">The main interval is entirely above zero.</h2></div></div><p class="viz-intro">Each dot is an estimate. Its horizontal line is the <strong>95% confidence interval</strong>. A line crossing zero includes no effect or no difference.</p>${forest([{...main,label:'Writer − nonwriter · difference in effects',focus:true},...D.groups.map(g=>({...g,label:g.label+' · program effect'}))])}<div class="viz-takeaway"><strong>The new comparison: +21.1 points, interval +6.9 to +35.3.</strong><span>The nonwriter interval crosses zero, but that alone is not evidence of different effects. The direct difference must be tested—and here its interval excludes zero.</span></div><div class="stat-explainer"><div><b>.004</b><span>Two-sided interaction p-value</span></div><div><b>.012</b><span>Holm p-value across three schooling outcomes</span></div><div><b>.0072</b><span>School-level wild-bootstrap p-value</span></div></div><p class="viz-source">Intervals use school-clustered standard errors. A p-value is not the probability that the finding is false. These analyses followed exploration; the three-outcome adjustment does not erase the wider search history.</p>`;}
 function checks(){return `<div class="viz-heading"><div><span class="viz-kicker">04 · Compare the checks on one scale</span><h2 id="visual-title">The estimated difference stays positive across these checks.</h2></div></div><p class="viz-intro">These lines all estimate the writer-minus-nonwriter difference in program effects. Every displayed 95% interval remains above zero.</p>${forest(D.checks.map((r,i)=>({...r,focus:i===0,note:`${count(r.n)} children · p = ${pval(r.p)}${i===3?' · selected-sample sensitivity':''}`})))}<p class="viz-source">The first three use the same 2,195 children. Excluding all ambiguous departure classifications uses 2,082 and can introduce selection differences. The December endpoint is a measurement-motivated sensitivity, not a repair of every coding or calendar-coverage issue.</p><button class="viz-next" data-visual="quality">Understand the data limitations →</button>`;}
 function quality(){const q=D.quality,flagged=q.both+q.codeOnly+q.windowOnly;return `<div class="viz-heading"><div><span class="viz-kicker">05 · Keep the measurement limits in view</span><h2 id="visual-title">230 records have at least one of two audit flags.</h2></div></div><div class="quality-layout"><figure class="quality-pie">${donut(flagged,D.n,'Records with at least one attendance-code or short-history flag').replaceAll('recorded departed','flagged').replaceAll('departed','flagged')}<figcaption><strong>${count(flagged)} of ${count(D.n)} children</strong><p>10.5% flagged by at least one audit</p></figcaption></figure><div class="quality-counts"><div><span>Ambiguous departure code only</span><strong>${q.codeOnly}</strong></div><div><span>Fewer than five open checks only</span><strong>${q.windowOnly}</strong></div><div><span>Both flags</span><strong>${q.both}</strong></div><div><span>Neither of these flags</span><strong>${count(q.neither)}</strong></div></div></div><p class="viz-intro">There are <strong>113</strong> ambiguous departure classifications and <strong>145</strong> short observation histories. They overlap for <strong>28</strong> children: 113 + 145 − 28 = 230. Each child is counted only once above.</p><div class="quality-explain"><p><strong>Attendance codes:</strong> the original program treats undocumented negative codes as absence. Excluding all 113 ambiguous departures leaves a positive interaction, but changes the sample.</p><p><strong>Observation opportunities:</strong> the program makes schools open more often. The last available open-school checks therefore need not cover the same dates in both groups.</p><p><strong>Departure ≠ leaving education:</strong> an exit may mean transfer or another destination. The primary result does not establish what happened afterwards.</p></div><p class="viz-source">“Neither flag” does not certify a perfect record. Treating all 230 flagged classifications as unknown gives an observed-sample range of +8.8 to +45.6 points. That is an algebraic bound, not a confidence interval or a guarantee of statistical significance under every coding.</p>`;}
 function contents(){const s=state();return `<div class="visual-top"><span class="visual-label">Explore the finding visually</span><span class="visual-basis">Same verified results · no new estimates</span></div><nav class="visual-tabs" aria-label="Visual explanations">${Object.entries(modes).map(([key,label],i)=>`<button data-visual="${key}" aria-pressed="${s.mode===key}"><span>${i+1}</span>${label}</button>`).join('')}</nav><div class="visual-content" aria-live="polite">${s.mode==='rates'?rates(s):s.mode==='difference'?difference():s.mode==='uncertainty'?uncertainty():s.mode==='checks'?checks():quality()}</div><div class="visual-footer"><span>Source: original roster data · 2,195 linked children · 111 schools</span><a href="#detailed-analysis">Read the full analysis ↓</a></div>`;}
 function render(){return `<section class="visual-lab" id="visual-lab" data-visual-host aria-labelledby="visual-title">${contents()}</section>`;}
 function update(mode,chart,push=true){const u=new URL(location.href);if(mode){if(!Object.hasOwn(modes,mode))throw new Error('Unknown visual');u.searchParams.set('visual',mode);}if(chart){if(!['bars','pies'].includes(chart))throw new Error('Unknown chart type');u.searchParams.set('chart',chart);}if(push)history.pushState(null,'',u);const host=document.querySelector('[data-visual-host]');if(host)host.innerHTML=contents();}
 document.addEventListener('click',e=>{const m=e.target.closest('[data-visual]'),c=e.target.closest('[data-chart]');if(m||c){update(m?.dataset.visual,c?.dataset.chart);const host=document.querySelector('[data-visual-host]');const button=host?.querySelector(m?`[data-visual="${m.dataset.visual}"]`:`[data-chart="${c.dataset.chart}"]`);button?.focus({preventScroll:true});if(host&&host.getBoundingClientRect().top<0)host.scrollIntoView({block:'start',behavior:'instant'});}});
 window.addEventListener('popstate',()=>update(null,null,false));
 window.studyVisuals={render,getState:state,show:update};
})();
